//! Golden differential tests against the Go implementation (fixtures generated by
//! `go run -mod=vendor ./hack/golden/kubeconfiginjection crates/ctrl-kubeconfiginjection/tests/fixtures`).
//!
//! Each scenario runs [`KubeconfigInjector`] / [`CleanupHandler`] /
//! [`find_provisioner_for_kubeconfig_secret`] against `ctrlrt-fake` with the same inputs as
//! the Go program and compares, byte for byte: every step's result, error string and events,
//! and the `encoding/json` bytes of the DPFHCPProvisioner (stored + in-memory), DPUCluster and
//! the source/destination Secrets.
//!
//! Normalization (also applied by the Go generator): condition `lastTransitionTime`
//! (`metav1.Now()`) is set to `2025-01-01T00:00:00Z`. `Secret` is a k8s-openapi type whose
//! serde field order differs from Go's; [`go_secret`] encodes it in Go field order with Go
//! `omitempty` rules (metadata via `apis::go`), so the comparison is still byte-exact.

use std::collections::BTreeMap;
use std::sync::Arc;

use apis::dpf::provisioning::v1alpha1 as dpuprovisioningv1alpha1;
use apis::k8s::core::v1::{LocalObjectReference, ObjectReference};
use apis::provisioning::v1alpha1 as provisioningv1alpha1;
use ctrl_kubeconfiginjection::{
    CleanupHandler, KubeconfigInjector, find_provisioner_for_kubeconfig_secret,
};
use ctrlrt::meta::CONDITION_TRUE;
use ctrlrt::{Client, Ctx, FakeRecorder, Object, ObjectKey, ReconcileResult};
use ctrlrt_fake::{FakeClientBuilder, InitObject, Scheme};
use k8s_openapi::ByteString;
use k8s_openapi::api::core::v1::{ConfigMap, Secret};
use k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, Time};
use serde::{Deserialize, Serialize};

const SECRET_NAME: &str = "test-provisioner-admin-kubeconfig";

#[derive(Debug, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
struct Step {
    requeue: bool,
    requeue_after: i64,
    error: String,
    events: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    steps: Option<Vec<Step>>,
    objects: BTreeMap<String, String>,
    #[serde(default)]
    requests: Vec<String>,
}

fn fixture(name: &str) -> Fixture {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

/// `json.Marshal(*corev1.Secret)`: Go field order and `omitempty`.
fn go_secret(s: &Secret) -> String {
    #[derive(Serialize)]
    struct GoSecret<'a> {
        metadata: apis::go::Go<'a, ObjectMeta>,
        #[serde(skip_serializing_if = "Option::is_none")]
        immutable: Option<bool>,
        #[serde(skip_serializing_if = "is_empty_map")]
        data: &'a Option<BTreeMap<String, ByteString>>,
        #[serde(rename = "stringData", skip_serializing_if = "is_empty_map")]
        string_data: &'a Option<BTreeMap<String, String>>,
        #[serde(rename = "type", skip_serializing_if = "is_empty_str")]
        type_: &'a Option<String>,
    }
    fn is_empty_map<V>(m: &&Option<BTreeMap<String, V>>) -> bool {
        m.as_ref().is_none_or(|m| m.is_empty())
    }
    fn is_empty_str(s: &&Option<String>) -> bool {
        s.as_deref().unwrap_or("").is_empty()
    }
    serde_json::to_string(&GoSecret {
        metadata: apis::go::Go(&s.metadata),
        immutable: s.immutable,
        data: &s.data,
        string_data: &s.string_data,
        type_: &s.type_,
    })
    .unwrap()
}

fn scheme() -> Scheme {
    Scheme::new()
        .register::<provisioningv1alpha1::DPFHCPProvisioner>()
        .register::<provisioningv1alpha1::DPFHCPProvisionerConfig>()
        .register::<Secret>()
        .register::<ConfigMap>()
        .register::<dpuprovisioningv1alpha1::DPUCluster>()
}

fn fixed_time() -> Time {
    Time("2025-01-01T00:00:00Z".parse().unwrap())
}

fn provisioner(with_hc: bool) -> provisioningv1alpha1::DPFHCPProvisioner {
    provisioningv1alpha1::DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some("test-provisioner".into()),
            namespace: Some("test-ns".into()),
            generation: Some(2),
            uid: Some("uid-1".into()),
            ..Default::default()
        },
        spec: provisioningv1alpha1::DPFHCPProvisionerSpec {
            dpu_cluster_ref: provisioningv1alpha1::DPUClusterReference {
                name: "test-dpu".into(),
                namespace: "dpu-ns".into(),
                ..Default::default()
            },
            ..Default::default()
        },
        status: provisioningv1alpha1::DPFHCPProvisionerStatus {
            hosted_cluster_ref: with_hc.then(|| ObjectReference {
                name: "test-provisioner".into(),
                namespace: "test-ns".into(),
                ..Default::default()
            }),
            ..Default::default()
        },
        ..Default::default()
    }
}

fn previously_injected(
    mut p: provisioningv1alpha1::DPFHCPProvisioner,
) -> provisioningv1alpha1::DPFHCPProvisioner {
    p.status.kube_config_secret_ref = Some(LocalObjectReference {
        name: SECRET_NAME.into(),
        ..Default::default()
    });
    let mut c = ctrlrt::meta::condition(
        provisioningv1alpha1::KUBE_CONFIG_INJECTED,
        CONDITION_TRUE,
        provisioningv1alpha1::REASON_KUBE_CONFIG_INJECTED,
        "Previously injected",
    );
    c.last_transition_time = fixed_time();
    ctrlrt::meta::set_status_condition(&mut p.status.conditions, c);
    p
}

fn data(pairs: &[(&str, &str)]) -> Option<BTreeMap<String, ByteString>> {
    Some(
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), ByteString(v.as_bytes().to_vec())))
            .collect(),
    )
}

fn source_secret(d: Option<BTreeMap<String, ByteString>>) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some(SECRET_NAME.into()),
            namespace: Some("test-ns".into()),
            labels: Some(BTreeMap::from([(
                "hypershift.openshift.io/hosted-control-plane".into(),
                "true".into(),
            )])),
            annotations: Some(BTreeMap::from([("source".into(), "hypershift".into())])),
            ..Default::default()
        },
        data: d,
        type_: Some("Opaque".into()),
        ..Default::default()
    }
}

fn dest_secret(d: Option<BTreeMap<String, ByteString>>) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some(SECRET_NAME.into()),
            namespace: Some("dpu-ns".into()),
            labels: Some(BTreeMap::from([("user".into(), "label".into())])),
            annotations: Some(BTreeMap::from([("keep".into(), "me".into())])),
            ..Default::default()
        },
        data: d,
        ..Default::default()
    }
}

fn dpu_cluster(kubeconfig: &str) -> dpuprovisioningv1alpha1::DPUCluster {
    dpuprovisioningv1alpha1::DPUCluster {
        metadata: ObjectMeta {
            name: Some("test-dpu".into()),
            namespace: Some("dpu-ns".into()),
            labels: Some(BTreeMap::from([("a".into(), "b".into())])),
            ..Default::default()
        },
        spec: dpuprovisioningv1alpha1::DPUClusterSpec {
            type_: dpuprovisioningv1alpha1::STATIC_CLUSTER.into(),
            max_nodes: 10,
            kubeconfig: kubeconfig.into(),
            ..Default::default()
        },
        ..Default::default()
    }
}

fn kc(v: &str) -> Option<BTreeMap<String, ByteString>> {
    data(&[("kubeconfig", v)])
}

fn sa(v: &str) -> Option<BTreeMap<String, ByteString>> {
    data(&[("super-admin.conf", v), ("extra", "e")])
}

fn step(res: ctrlrt::Result<ReconcileResult>, rec: &FakeRecorder) -> Step {
    let (r, error) = match res {
        Ok(r) => (r, String::new()),
        Err(e) => (ReconcileResult::default(), e.to_string()),
    };
    Step {
        requeue: r.requeue,
        requeue_after: r.requeue_after.as_nanos() as i64,
        error,
        events: rec.drain(),
    }
}

fn normalize(p: &mut provisioningv1alpha1::DPFHCPProvisioner) {
    for c in &mut p.status.conditions {
        c.last_transition_time = fixed_time();
    }
}

async fn dump(
    c: &Client,
    p: &mut provisioningv1alpha1::DPFHCPProvisioner,
) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    normalize(p);
    out.insert(
        "provisioner.memory".into(),
        serde_json::to_string(p).unwrap(),
    );
    let stored = c
        .get::<provisioningv1alpha1::DPFHCPProvisioner>(&ObjectKey::new(
            "test-ns",
            "test-provisioner",
        ))
        .await
        .ok()
        .map(|mut s| {
            normalize(&mut s);
            serde_json::to_string(&s).unwrap()
        });
    out.insert("provisioner.stored".into(), stored.unwrap_or_default());
    let dpu = c
        .get::<dpuprovisioningv1alpha1::DPUCluster>(&ObjectKey::new("dpu-ns", "test-dpu"))
        .await
        .ok()
        .map(|o| serde_json::to_string(&o).unwrap());
    out.insert("dpucluster".into(), dpu.unwrap_or_default());
    for (label, ns) in [("secret.source", "test-ns"), ("secret.dest", "dpu-ns")] {
        let s = c
            .get::<Secret>(&ObjectKey::new(ns, SECRET_NAME))
            .await
            .ok()
            .map(|s| go_secret(&s));
        out.insert(label.into(), s.unwrap_or_default());
    }
    out
}

fn compare(name: &str, got_steps: Option<Vec<Step>>, got_objects: BTreeMap<String, String>) {
    let want = fixture(name);
    assert_eq!(got_steps, want.steps, "{name}: steps differ from Go");
    assert_eq!(
        got_objects.keys().collect::<Vec<_>>(),
        want.objects.keys().collect::<Vec<_>>(),
        "{name}: object set"
    );
    for (k, w) in &want.objects {
        assert_eq!(&got_objects[k], w, "{name}: {k} differs from Go");
    }
}

async fn run_inject(
    name: &str,
    mut p: provisioningv1alpha1::DPFHCPProvisioner,
    objs: Vec<InitObject>,
    runs: usize,
) {
    let ctx = Ctx::background();
    let mut all = vec![ctrlrt_fake::obj_mut(&mut p)];
    all.extend(objs);
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(all)
        .with_status_subresource::<provisioningv1alpha1::DPFHCPProvisioner>()
        .with_status_subresource::<dpuprovisioningv1alpha1::DPUCluster>()
        .build();
    let rec = Arc::new(FakeRecorder::new(100));
    let ki = KubeconfigInjector::new(c.clone(), rec.clone());
    let mut steps = Vec::new();
    for _ in 0..runs {
        let res = ki.inject_kubeconfig(&ctx, &mut p).await;
        steps.push(step(res, &rec));
    }
    let objects = dump(&c, &mut p).await;
    compare(name, Some(steps), objects);
}

#[tokio::test]
async fn inject_happy() {
    let objs = vec![
        ctrlrt_fake::obj(&source_secret(kc("fake-kubeconfig-data"))),
        ctrlrt_fake::obj(&dpu_cluster("")),
    ];
    run_inject("inject_happy", provisioner(true), objs, 2).await;
}

#[tokio::test]
async fn inject_drift() {
    let objs = vec![
        ctrlrt_fake::obj(&source_secret(kc("new-rotated"))),
        ctrlrt_fake::obj(&dest_secret(sa("old"))),
        ctrlrt_fake::obj(&dpu_cluster(SECRET_NAME)),
    ];
    run_inject(
        "inject_drift",
        previously_injected(provisioner(true)),
        objs,
        1,
    )
    .await;
}

