fn labelled(name: &str, ns: &str, owner: bool) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some(name.into()),
            namespace: Some(ns.into()),
            labels: owner.then(|| {
                BTreeMap::from([
                    (
                        common::LABEL_DPFHCP_PROVISIONER_NAME.to_string(),
                        "test-provisioner".to_string(),
                    ),
                    (
                        common::LABEL_DPFHCP_PROVISIONER_NAMESPACE.to_string(),
                        "test-ns".to_string(),
                    ),
                ])
            }),
            ..Default::default()
        },
        data: data(&[("super-admin.conf", "x")]),
        ..Default::default()
    }
}

async fn run_cleanup(name: &str, objs: Vec<InitObject>, runs: usize) {
    let ctx = Ctx::background();
    let mut p = provisioner(true);
    let mut all = vec![ctrlrt_fake::obj_mut(&mut p)];
    all.extend(objs);
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(all)
        .build();
    let rec = Arc::new(FakeRecorder::new(100));
    let h = CleanupHandler::new(c.clone(), rec.clone());
    let mut steps = Vec::new();
    for _ in 0..runs {
        let res = h.cleanup(&ctx, &p).await;
        steps.push(step(res, &rec));
    }
    let mut objects = BTreeMap::new();
    for s in c.list_all::<Secret>().await.unwrap() {
        objects.insert(
            format!("secret {}/{}", s.namespace(), s.name()),
            go_secret(&s),
        );
    }
    compare(name, Some(steps), objects);
}

#[tokio::test]
async fn cleanup_secrets() {
    let objs = vec![
        ctrlrt_fake::obj(&labelled(SECRET_NAME, "dpu-ns", true)),
        ctrlrt_fake::obj(&labelled("another", "other-ns", true)),
        ctrlrt_fake::obj(&labelled("unrelated", "dpu-ns", false)),
    ];
    run_cleanup("cleanup_secrets", objs, 2).await;
}

