async fn cleanup_none() {
    run_cleanup("cleanup_none", vec![], 1).await;
}

#[tokio::test]
async fn map_requests() {
    let ctx = Ctx::background();
    let other = provisioningv1alpha1::DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some("a-admin-kubeconfig".into()),
            namespace: Some("x".into()),
            ..Default::default()
        },
        ..Default::default()
    };
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects([
            ctrlrt_fake::obj(&provisioner(true)),
            ctrlrt_fake::obj(&other),
        ])
        .build();

    let secret = |name: &str, ns: &str| Secret {
        metadata: ObjectMeta {
            name: Some(name.into()),
            namespace: Some(ns.into()),
            ..Default::default()
        },
        ..Default::default()
    };
    let mut requests = Vec::new();
    let mut record = |id: String, reqs: Vec<ObjectKey>| {
        for r in &reqs {
            requests.push(format!("{id} -> {r}"));
        }
        requests.push(format!("{id}: {}", reqs.len()));
    };
    for s in [
        secret(SECRET_NAME, "test-ns"),
        secret(SECRET_NAME, "other"),
        secret("a-admin-kubeconfig-admin-kubeconfig", "x"),
        secret("test-provisioner", "test-ns"),
    ] {
        let reqs = find_provisioner_for_kubeconfig_secret(&ctx, &c, &s).await;
        record(format!("{}/{}", s.namespace(), s.name()), reqs);
    }
    let cm = ConfigMap {
        metadata: ObjectMeta {
            name: Some(SECRET_NAME.into()),
            namespace: Some("test-ns".into()),
            ..Default::default()
        },
        ..Default::default()
    };
    let reqs = find_provisioner_for_kubeconfig_secret(&ctx, &c, &cm).await;
    record(format!("{}/{}", cm.namespace(), cm.name()), reqs);

    let want = fixture("map_requests");
    assert!(want.steps.is_none() && want.objects.is_empty());
    assert_eq!(requests, want.requests);
}

/// Not a Go spec: checks the `ctrl_finalizer::CleanupHandler` impl delegates to the
/// inherent methods.
#[tokio::test]
async fn finalizer_cleanup_handler_trait_impl() {
    let ctx = Ctx::background();
    let mut p = provisioner(true);
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects([
            ctrlrt_fake::obj_mut(&mut p),
            ctrlrt_fake::obj(&labelled(SECRET_NAME, "dpu-ns", true)),
        ])
        .build();
    let rec = Arc::new(FakeRecorder::new(100));
    let h: Box<dyn ctrl_finalizer::CleanupHandler> =
        Box::new(CleanupHandler::new(c.clone(), rec.clone()));
    assert_eq!(h.name(), "kubeconfig-injection");
    assert!(h.cleanup(&ctx, &p).await.unwrap().is_zero());
    assert_eq!(
        rec.drain(),
        vec!["Normal KubeconfigCleanupSucceeded Deleted 1 kubeconfig secret(s)".to_string()]
    );
    assert!(c.list_all::<Secret>().await.unwrap().is_empty());
}
